// th15_s6_b8 — TH15 Stage 6 BossCard4 「震え凍える星」
// Source entry: st06bs.ecl.txt:1485-1551 (BossCard4)
// Ring emitter: st06bs.ecl.txt:1553-1578 (BossCard4_at)
// Card frame 0 = segment timer start; attack (source script time 94) begins after
// OPENING_BUFFER, which absorbs the source's clear/timerReset/setup lead-in.

const TIME_LIMIT: int = 3124;
const OPENING_BUFFER: int = 120;

// TH15 synthetic catalog alias: source type 5 (etSprite(0,5,6)) -> TH15_BALL2, base radius 4, color 6.
const TH15_BALL2: int = 432;
const SPRAY_COLOR: int = 6;      // etSprite(0, 5, 6): color slot 6
const SPELL_CARD: int = 90;      // source spell id (spell(90, 3000, 500000, ...))

async sub boss_enemy() {
    set_invuln(65535);
    // entry state from Boss() context: hurtbox 56x56, hitbox 50x50 -> radii 28 / 25
    set_hurtbox(28fx);
    set_hitbox(25fx);
    // movePosTime(60, 4, 0.0f, 128.0f): already at (0,128) from entry, mode4 = EASE_QUAD_OUT.
    // moveLimit(0,128,240,64) is inert while stationary and has no target API (see report).
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);

    // diffI: A = 30/42/66/88, I0 = 56/80/80/88, E = 5/5/7/7 (Easy..Lunatic).
    var rank: int = global(GVAR_RANK);
    var count: int = 30;
    var cap: int = 56;
    var rings: int = 5;
    if rank == RANK_NORMAL { count = 42; cap = 80; }
    if rank == RANK_HARD { count = 66; cap = 80; rings = 7; }
    if rank == RANK_LUNATIC { count = 88; cap = 88; rings = 7; }

    sh_reset(0);
    sh_sprite(0, TH15_BALL2, SPRAY_COLOR);
    sh_ring(0, 1);          // etAim(0,3): fixed-direction full ring
    sh_aim(0, 0);           // no player aim
    sh_speed(0, 1.5fx, 0fx); // etSpeed(0,1.5,0.2) with 1 layer -> first speed only
    // ANIM a=1 birth retreat (position -= 4*velocity) = 6px inward along each bullet's angle.
    sh_dist(0, -6fx);

    loop {
        sh_count(0, count, 1);              // etCount(0, A, 1)
        var base: int = rand(65536) - 32768; // %RANDRAD once per group, BAM (-pi..pi)
        var half: int = 32768 / count;       // (7.?/A)/2 = pi/A in BAM
        for k in 0..rings {
            sh_angle(0, (base + k * half) as angle, 0deg); // C += D/2 each ring
            sh_fire(0);
            wait(13);
        }
        if count < cap { count = count + 6; }  // grow A by 6 until it reaches I0
        wait(26);
    }
}

async sub boss_phase() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, SPELL_CARD, boss_phase, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
